import sys

def main():
    books = {}
    MAX_BOOKS = 100
    MAX_TITLE_LENGTH = 50

    while True:
        print("1. Add a book")
        print("2. Search for a book by ID")
        print("3. Delete a book by ID")
        print("4. Display all books")
        print("5. Exit")
        print("Choose an option: ", end="")
        sys.stdout.flush()

        option = sys.stdin.readline().strip()

        if option == '1':
            if len(books) >= MAX_BOOKS:
                print("Cannot add more books. Maximum limit reached.")
                continue

            print("Enter Book ID: ", end="")
            sys.stdout.flush()
            book_id_line = sys.stdin.readline().strip()
            try:
                book_id = int(book_id_line)
            except:
                print("Invalid book ID.")
                continue

            print("Enter Book Title: ", end="")
            sys.stdout.flush()
            title = sys.stdin.readline().strip()
            if title.startswith('"') and title.endswith('"'):
                title = title[1:-1]

            if len(title) > MAX_TITLE_LENGTH:
                print("Title exceeds maximum length.")
                continue

            books[book_id] = title
            print("Book added successfully.")

        elif option == '2':
            print("Enter Book ID: ", end="")
            sys.stdout.flush()
            search_id_line = sys.stdin.readline().strip()
            try:
                search_id = int(search_id_line)
            except:
                print("Invalid book ID.")
                continue

            if search_id in books:
                print(f"Book found: ID={search_id}, Title=\"{books[search_id]}\"")
            else:
                print("Book not found.")

        elif option == '3':
            print("Enter Book ID: ", end="")
            sys.stdout.flush()
            delete_id_line = sys.stdin.readline().strip()
            try:
                delete_id = int(delete_id_line)
            except:
                print("Invalid book ID.")
                continue

            if delete_id in books:
                del books[delete_id]
                print("Book deleted successfully.")
            else:
                print("Book ID not found.")

        elif option == '4':
            for book_id, title in books.items():
                print(f"Book ID={book_id}, Title=\"{title}\"")

        elif option == '5':
            print("Exiting the program...")
            break

if __name__ == "__main__":
    main()
